1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	export type Step = { op: string; items?: Item[] };
8	export type Customer = { yearsWithMHPCO: number };
9	export type Scenario = { customer: Customer; steps: Step[] };
10	
11	export type StepResult = { premium: number };
12	export type ScenarioResult = { results: StepResult[] };
