14	const BASE_PREMIUMS: Record<string, number> = {
15	  sword: 100,
16	  amulet: 60,
17	  staff: 80,
18	  potion: 40,
19	  rune: 25,
20	  moonstone: 25,
21	};
22	
23	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
24	const PROCESSING_FEE = 5;
25	
26	const CURSE_SURCHARGE_RATE = 0.5;
27	const HIGH_ENCHANTMENT_THRESHOLD = 5;
28	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
29	const LOYALTY_THRESHOLD_YEARS = 2;
30	const LOYALTY_DISCOUNT_RATE = 0.2;
31	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
32	
33	const BLOCK_SIZE = 3;
34	const BLOCK_BASE_PREMIUM = 60;
35	
36	const countByType = (items: Item[]): Map<string, number> => {
37	  const counts = new Map<string, number>();
38	  for (const item of items) {
39	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
40	  }
41	  return counts;
42	};
43	
44	const basePremiumForType = (type: string, count: number): number =>
45	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
46	
47	const policyBasePremium = (items: Item[]): number =>
48	  [...countByType(items)]
49	    .map(([type, count]) => basePremiumForType(type, count))
50	    .reduce((total, premium) => total + premium, 0);
51	
52	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
53	
54	const isCursed = (item: Item): boolean => item.cursed === true;
55	
56	const isHighlyEnchanted = (item: Item): boolean =>
57	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
58	
59	const curseSurcharge = (item: Item): number =>
60	  isCursed(item) ? itemBasePremium(item) * CURSE_SURCHARGE_RATE : 0;
61	
62	const highEnchantmentSurcharge = (item: Item): number =>
63	  isHighlyEnchanted(item)
64	    ? itemBasePremium(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
65	    : 0;
66	
67	const itemModifierSurcharges = (items: Item[]): number =>
68	  items
69	    .map((item) => curseSurcharge(item) + highEnchantmentSurcharge(item))
70	    .reduce((total, surcharge) => total + surcharge, 0);
71	
72	const isLoyalCustomer = (customer: Customer): boolean =>
73	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
74	
75	// Policy-wide modifiers are rates applied to the policy base premium.
76	// Surcharges are positive, discounts negative; they sum to one net rate.
77	const policyModifierRates = (
78	  customer: Customer,
79	  isFollowUpContract: boolean,
80	): number[] => [
81	  FIRST_INSURANCE_SURCHARGE_RATE,
82	  isLoyalCustomer(customer) ? -LOYALTY_DISCOUNT_RATE : 0,
83	  isFollowUpContract ? -FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0,
84	];
85	
86	const netPolicyModifierRate = (
87	  customer: Customer,
88	  isFollowUpContract: boolean,
89	): number =>
90	  policyModifierRates(customer, isFollowUpContract).reduce(
91	    (total, rate) => total + rate,
92	    0,
93	  );
94	
95	const quotePremium = (
96	  customer: Customer,
97	  items: Item[] = [],
98	  isFollowUpContract = false,
99	): number => {
100	  const policyBase = policyBasePremium(items);
101	  const policyModifiers =
102	    policyBase * netPolicyModifierRate(customer, isFollowUpContract);
103	  return Math.ceil(
104	    policyBase +
105	      itemModifierSurcharges(items) +
106	      policyModifiers +
107	      PROCESSING_FEE,
108	  );
109	};
110	
111	export const runScenario = (scenario: Scenario): ScenarioResult => {
112	  let quotesSoFar = 0;
113	  const results = scenario.steps.map((step) => {
114	    const isFollowUpContract = quotesSoFar > 0;
115	    quotesSoFar += 1;
116	    return {
117	      premium: quotePremium(scenario.customer, step.items, isFollowUpContract),
118	    };
119	  });
120	  return { results };
121	};
